SELECT id, interval_code, candle_open_time, generated_at, signal_mode, data_quality_valid, decision, original_decision, total_score, confidence_score, latest_price FROM crypto_ai.trade_signal WHERE symbol = 'EGLDUSDT' AND ((interval_code = '1h' AND generated_at BETWEEN '2026-10-11 20:55:00' AND '2026-10-11 22:44:00') OR (interval_code = '5m' AND generated_at BETWEEN '2026-10-11 22:30:00' AND '2026-10-11 22:44:00') OR (interval_code = '1m' AND generated_at BETWEEN '2026-10-11 22:39:00' AND '2026-10-11 22:44:00')) ORDER BY generated_at LIMIT 60